import { describe, expect, it } from "vitest";
import { BOARD_EXPANSION_20260912_CASES } from "@gamify-surgery/clinical-content";
import {
  createInitialGameState,
  createPatientPixelAppearance,
  deserializeGameState,
  gameReducer,
  getCurrentQuestion,
  serializeGameState,
  type GameState,
} from "../src";

function prepared(seed: string): GameState {
  const state = createInitialGameState(undefined, {
    campaignId: `campaign.board.20260912.${seed}`,
    campaignSeed: seed,
    createdAtRealMs: 0,
  });
  state.facilityLevel = 1;
  // This ordinary-care batch authors the connected clinical room that a fresh
  // campaign now requires the player to construct.
  state.rooms.push({
    id: "room.board.20260912.examination",
    roomDefinitionId: "room.examination",
    x: 34,
    y: 26,
    orientation: 0,
    doorSide: "south",
    upgradeLevel: 1,
    cleanliness: 100,
  });
  state.doors.push({
    id: "door.board.20260912.examination",
    roomId: "room.board.20260912.examination",
    side: "south",
    offset: 1,
    exterior: false,
  });
  state.encounters = {};
  state.openChartEncounterId = null;
  state.attendedEncounterId = null;
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  return state;
}

function ready(state: GameState, encounterId: string, prefix: string): GameState {
  let next = state;
  for (let attempt = 0; attempt < 1_500; attempt += 1) {
    if (getCurrentQuestion(next, encounterId)) return next;
    const encounter = next.encounters[encounterId]!;
    next = encounter.lifecycle === "waiting_unopened" && encounter.patientMovement === null
      ? gameReducer(next, { type: "OPEN_CHART", operationId: `${prefix}.open.${attempt}`, encounterId })
      : gameReducer(next, { type: "ADVANCE_TICK", operationId: `${prefix}.tick.${attempt}` });
  }
  throw new Error(`${encounterId} did not become ready`);
}

function submit(state: GameState, encounterId: string, correct: boolean, operationId: string, reviewedAtMs: number): GameState {
  const question = getCurrentQuestion(state, encounterId)!;
  const choice = question.node.answerChoices.find((item) => item.isCorrect === correct)!;
  return gameReducer(state, {
    type: "SUBMIT_ANSWER",
    operationId,
    encounterId,
    decisionNodeId: question.node.id,
    answerChoiceId: choice.id,
    reviewedAtMs,
  });
}

function acknowledge(state: GameState, encounterId: string, operationId: string): GameState {
  const encounter = state.encounters[encounterId]!;
  return gameReducer(state, {
    type: "ACKNOWLEDGE_DECISION_FEEDBACK",
    operationId,
    encounterId,
    decisionNodeId: encounter.steps[encounter.currentNodeIndex]!.decisionNodeId,
  });
}

describe("September 12 board-expansion production flows", () => {
  it.each(BOARD_EXPANSION_20260912_CASES.map((clinicalCase, index) => [index, clinicalCase] as const))(
    "runs case %s through its real gate with one review per concept",
    (index, clinicalCase) => {
      const encounterId = `encounter.board.20260912.${index}`;
      let state = prepared(`all-${index}`);
      state = gameReducer(state, {
        type: "ADMIT_PATIENT",
        operationId: `board.20260912.${index}.admit`,
        encounterId,
        caseId: clinicalCase.id,
        patientDisplayName: `Board Patient ${index}`,
        arrivalClass: "routine",
      });
      expect(state.operationReceipts[`board.20260912.${index}.admit`]?.status).toBe("applied");
      state = ready(state, encounterId, `board.20260912.${index}.first`);
      const first = getCurrentQuestion(state, encounterId)!;
      expect(first.node.primaryConceptId).toBe(clinicalCase.decisionNodes[0]!.primaryConceptId);
      state = submit(state, encounterId, true, `board.20260912.${index}.first.answer`, index + 1);
      expect(state.encounters[encounterId]!.steps[0]!.status).toBe("feedback_pending");
      state = acknowledge(state, encounterId, `board.20260912.${index}.first.ack`);
      const pending = state.encounters[encounterId]!.pendingResult!;
      expect(pending).toMatchObject({ resultTypeId: clinicalCase.decisionNodes[0]!.resultGateAfter!.resultTypeId });
      expect(pending.dueTick).toBeGreaterThan(state.facilityTick);
      while (state.facilityTick < pending.dueTick) {
        expect(getCurrentQuestion(state, encounterId)).toBeNull();
        expect(state.encounters[encounterId]!.deliveredResultNarratives).toEqual([]);
        state = gameReducer(state, { type: "ADVANCE_TICK", operationId: `board.20260912.${index}.wait.${state.facilityTick}` });
      }
      state = ready(state, encounterId, `board.20260912.${index}.second`);
      expect(state.encounters[encounterId]!.deliveredResultNarratives).toContain(clinicalCase.decisionNodes[0]!.resultGateAfter!.resultNarrative);
      const second = getCurrentQuestion(state, encounterId)!;
      expect(second.node.primaryConceptId).toBe(clinicalCase.decisionNodes[1]!.primaryConceptId);
      state = submit(state, encounterId, true, `board.20260912.${index}.second.answer`, index + 10_000);
      expect(state.encounters[encounterId]!).toMatchObject({ lifecycle: "resolved_summary_available", resolutionReason: "completed" });
      expect(state.encounters[encounterId]!.pendingResult).toMatchObject({ deliveredAtTick: expect.any(Number) });
      expect(state.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);
      expect(state.learningHistories[second.node.primaryConceptId]?.reviews).toHaveLength(1);
    },
  );

  it("corrects forward after a wrong answer and preserves pending state, identity, order, and FSRS review through reload", () => {
    const clinicalCase = BOARD_EXPANSION_20260912_CASES[0]!;
    const encounterId = "encounter.board.20260912.persistence";
    let state = prepared("persistence");
    state = gameReducer(state, {
      type: "ADMIT_PATIENT",
      operationId: "board.20260912.persist.admit",
      encounterId,
      caseId: clinicalCase.id,
      patientDisplayName: "Persistent Patient",
      arrivalClass: "routine",
    });
    const frozen = state.encounters[encounterId]!.frozenCase;
    const appearance = state.encounters[encounterId]!.patientAppearance;
    expect(appearance).toEqual(createPatientPixelAppearance(state.campaignSeed, encounterId, frozen.prototypeDemographics!));
    state = ready(state, encounterId, "board.20260912.persist");
    const first = getCurrentQuestion(state, encounterId)!;
    const frozenOrder = first.node.answerChoices.map((choice) => choice.id);
    state = submit(state, encounterId, false, "board.20260912.persist.answer", 99);
    expect(state.encounters[encounterId]!.steps[0]!.answer).toMatchObject({ correct: false, correctedForward: true, ratingIntent: "Again" });
    expect(state.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);
    state = acknowledge(state, encounterId, "board.20260912.persist.ack");
    const pending = state.encounters[encounterId]!.pendingResult!;
    expect(pending.resultTypeId).toBe(clinicalCase.decisionNodes[0]!.resultGateAfter!.resultTypeId);
    expect(pending.dueTick).toBeGreaterThan(state.facilityTick);
    const restored = deserializeGameState(serializeGameState(state));
    expect(restored.encounters[encounterId]!.pendingResult).toEqual(pending);
    expect(restored.encounters[encounterId]!.frozenCase).toEqual(frozen);
    expect(restored.encounters[encounterId]!.patientAppearance).toEqual(appearance);
    expect(restored.encounters[encounterId]!.patientDisplayName).toBe("Persistent Patient");
    expect(restored.encounters[encounterId]!.frozenCase.decisionNodes[0]!.answerChoices.map((choice) => choice.id)).toEqual(frozenOrder);
    expect(restored.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);
  });
});

import { describe, expect, it } from "vitest";
import { EARLY_LEVELS_20260913_CASES, SYNTHETIC_CLINICAL_RELEASE } from "@gamify-surgery/clinical-content";
import { createInitialGameState, deserializeGameState, gameReducer, getCurrentQuestion, serializeGameState, type GameState } from "../src";

function prepared(seed:string,level:0|1|2=2):GameState{const state=createInitialGameState(undefined,{campaignId:`campaign.early.${seed}`,campaignSeed:seed,createdAtRealMs:0});state.facilityLevel=level;state.encounters={};state.openChartEncounterId=null;state.attendedEncounterId=null;state.nextRoutineArrivalTick=Number.MAX_SAFE_INTEGER;state.rooms.push({id:"room.early.examination",roomDefinitionId:"room.examination",x:29,y:23,orientation:0,doorSide:null,upgradeLevel:1,cleanliness:100},{id:"room.early.minor-procedure",roomDefinitionId:"room.minor_procedure",x:33,y:23,orientation:0,doorSide:null,upgradeLevel:1,cleanliness:100},...([24,25,26,27,28] as const).map((y)=>({id:`room.early.hall.${y}`,roomDefinitionId:"room.hallway",x:32,y,orientation:0 as const,doorSide:null,upgradeLevel:1 as const,cleanliness:100})));state.doors.push({id:"door.early.examination",roomId:"room.early.examination",side:"east",offset:1,exterior:false},{id:"door.early.minor-procedure",roomId:"room.early.minor-procedure",side:"west",offset:1,exterior:false},{id:"door.early.front",roomId:"room.instance.founder_desk",side:"west",offset:0,exterior:false});return state;}
function ready(state:GameState,encounterId:string,prefix:string):GameState{let next=state;for(let attempt=0;attempt<1500;attempt+=1){if(getCurrentQuestion(next,encounterId))return next;const encounter=next.encounters[encounterId]!;next=encounter.lifecycle==="waiting_unopened"&&encounter.patientMovement===null?gameReducer(next,{type:"OPEN_CHART",operationId:`${prefix}.open.${attempt}`,encounterId}):gameReducer(next,{type:"ADVANCE_TICK",operationId:`${prefix}.tick.${attempt}`});}throw new Error(`${encounterId} did not become ready`);}
function submit(state:GameState,encounterId:string,correct:boolean,operationId:string,reviewedAtMs:number){const question=getCurrentQuestion(state,encounterId)!;const choice=question.node.answerChoices.find((item)=>item.isCorrect===correct)!;return gameReducer(state,{type:"SUBMIT_ANSWER",operationId,encounterId,decisionNodeId:question.node.id,answerChoiceId:choice.id,reviewedAtMs});}
function acknowledge(state:GameState,encounterId:string,operationId:string){const encounter=state.encounters[encounterId]!;return gameReducer(state,{type:"ACKNOWLEDGE_DECISION_FEEDBACK",operationId,encounterId,decisionNodeId:encounter.steps[encounter.currentNodeIndex]!.decisionNodeId});}

// Validate delivered prose against the current authored case; retain every
// original gate identity, wait/reload assertion and historical source batch.
const liveCases = EARLY_LEVELS_20260913_CASES.map(source => SYNTHETIC_CLINICAL_RELEASE.cases.find(c => c.id === source.id)!);
describe("September 13 early-level production flows",()=>{
 it.each(liveCases.map((clinicalCase,index)=>[index,clinicalCase] as const))("runs case %s through each authored node with one FSRS review",(index,clinicalCase)=>{const encounterId=`encounter.early.${index}`;const stage=clinicalCase.earliestFacilityStage;if(stage!==0&&stage!==1&&stage!==2)throw new Error(`Early-level case ${clinicalCase.id} has an unexpected facility stage ${stage}`);let state=prepared(`all-${index}`,stage);state=gameReducer(state,{type:"ADMIT_PATIENT",operationId:`early.${index}.admit`,encounterId,caseId:clinicalCase.id,patientDisplayName:`Early Patient ${index}`,arrivalClass:"routine"});expect(state.operationReceipts[`early.${index}.admit`]?.status).toBe("applied");state=ready(state,encounterId,`early.${index}.first`);const first=getCurrentQuestion(state,encounterId)!;state=submit(state,encounterId,true,`early.${index}.first.answer`,index+1);expect(state.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);if(clinicalCase.decisionNodes.length===1){expect(state.encounters[encounterId]).toMatchObject({lifecycle:"resolved_summary_available",resolutionReason:"completed",pendingResult:null});return;}state=acknowledge(state,encounterId,`early.${index}.first.ack`);const gate=clinicalCase.decisionNodes[0]!.resultGateAfter!;const pending=state.encounters[encounterId]!.pendingResult!;expect(pending).toMatchObject({resultTypeId:gate.resultTypeId});expect(pending.dueTick).toBeGreaterThan(state.facilityTick);while(state.facilityTick<pending.dueTick){expect(getCurrentQuestion(state,encounterId)).toBeNull();expect(state.encounters[encounterId]!.deliveredResultNarratives).toEqual([]);state=gameReducer(state,{type:"ADVANCE_TICK",operationId:`early.${index}.wait.${state.facilityTick}`});}state=ready(state,encounterId,`early.${index}.second`);expect(state.encounters[encounterId]!.deliveredResultNarratives).toContain(gate.resultNarrative);const second=getCurrentQuestion(state,encounterId)!;expect(second.node.primaryConceptId).toBe(clinicalCase.decisionNodes[1]!.primaryConceptId);state=submit(state,encounterId,true,`early.${index}.second.answer`,index+10000);expect(state.encounters[encounterId]).toMatchObject({lifecycle:"resolved_summary_available",resolutionReason:"completed"});expect(state.learningHistories[second.node.primaryConceptId]?.reviews).toHaveLength(1);});

 it("rejects a case before its authored facility stage",()=>{const state=gameReducer(prepared("stage",0),{type:"ADMIT_PATIENT",operationId:"early.stage.reject",encounterId:"encounter.stage",caseId:"case.pancreatic-pseudocyst.early-satiety",patientDisplayName:"Stage Patient",arrivalClass:"routine"});expect(state.operationReceipts["early.stage.reject"]).toMatchObject({status:"rejected",message:"This patient becomes eligible at Level 2."});expect(state.encounters["encounter.stage"]).toBeUndefined();});

 it("resolves urgent asplenia fever without scheduling a test",()=>{const encounterId="encounter.urgent";let state=gameReducer(prepared("urgent",0),{type:"ADMIT_PATIENT",operationId:"early.urgent.admit",encounterId,caseId:"case.asplenia-fever.evening-fever",patientDisplayName:"Urgent Patient",arrivalClass:"routine"});state=ready(state,encounterId,"early.urgent");state=submit(state,encounterId,true,"early.urgent.answer",1);expect(state.encounters[encounterId]).toMatchObject({lifecycle:"resolved_summary_available",resolutionReason:"completed",pendingResult:null});});

 it("preserves a corrected-forward pending result, identity, due tick, and choice order through reload",()=>{const clinicalCase=EARLY_LEVELS_20260913_CASES.find((item)=>item.id==="case.lynch-tumor.new-diagnosis")!;const encounterId="encounter.persist";let state=gameReducer(prepared("persist",1),{type:"ADMIT_PATIENT",operationId:"early.persist.admit",encounterId,caseId:clinicalCase.id,patientDisplayName:"Persistent Patient",arrivalClass:"routine"});state=ready(state,encounterId,"early.persist");const first=getCurrentQuestion(state,encounterId)!;const order=first.node.answerChoices.map((choice)=>choice.id);state=submit(state,encounterId,false,"early.persist.answer",99);expect(state.encounters[encounterId]!.steps[0]!.answer).toMatchObject({correct:false,correctedForward:true,ratingIntent:"Again"});state=acknowledge(state,encounterId,"early.persist.ack");const pending=state.encounters[encounterId]!.pendingResult!;const restored=deserializeGameState(serializeGameState(state));expect(restored.encounters[encounterId]!.pendingResult).toEqual(pending);expect(restored.encounters[encounterId]!.pendingResult?.dueTick).toBe(pending.dueTick);expect(restored.encounters[encounterId]!.patientDisplayName).toBe("Persistent Patient");expect(restored.encounters[encounterId]!.frozenCase).toEqual(state.encounters[encounterId]!.frozenCase);expect(restored.encounters[encounterId]!.frozenCase.decisionNodes[0]!.answerChoices.map((choice)=>choice.id)).toEqual(order);expect(restored.learningHistories[first.node.primaryConceptId]?.reviews).toHaveLength(1);});
});

import { describe, expect, it } from "vitest";
import {
  TWENTY_CONCEPT_BATCH_CASES,
  TWENTY_CONCEPT_BATCH_CONCEPTS,
  TWENTY_CONCEPT_BATCH_QUESTIONS,
} from "@gamify-surgery/clinical-content";
import {
  PROTOTYPE_DOMAIN_CONTEXT,
  createInitialGameState,
  createPatientPixelAppearance,
  deserializeGameState,
  gameReducer,
  getCurrentQuestion,
  getEligibleServiceRoute,
  serializeGameState,
  type GameState,
} from "../src";

function emptyState(seed: string, level: 0 | 1 | 2): GameState {
  const state = createInitialGameState(undefined, {
    campaignId: `campaign.batch.${seed}`,
    campaignSeed: seed,
    createdAtRealMs: 0,
  });
  state.facilityLevel = level;
  // Ordinary-care batch fixtures require a reachable clinical room. Fresh
  // campaigns intentionally no longer receive this room automatically.
  state.rooms.push({
    id: "room.batch.examination",
    roomDefinitionId: "room.examination",
    x: 34,
    y: 26,
    orientation: 0,
    doorSide: "south",
    upgradeLevel: 1,
    cleanliness: 100,
  });
  state.doors.push({
    id: "door.batch.examination",
    roomId: "room.batch.examination",
    side: "south",
    offset: 1,
    exterior: false,
  });
  state.encounters = {};
  state.openChartEncounterId = null;
  state.attendedEncounterId = null;
  state.nextRoutineArrivalTick = Number.MAX_SAFE_INTEGER;
  return state;
}

function tick(state: GameState, id: string): GameState {
  return gameReducer(state, { type: "ADVANCE_TICK", operationId: id });
}

function ready(state: GameState, encounterId: string, prefix: string): GameState {
  let next = state;
  for (let attempt = 0; attempt < 250; attempt += 1) {
    if (getCurrentQuestion(next, encounterId)) return next;
    const encounter = next.encounters[encounterId]!;
    if (encounter.lifecycle === "waiting_unopened" && encounter.patientMovement === null) {
      next = gameReducer(next, { type: "OPEN_CHART", operationId: `${prefix}.open.${attempt}`, encounterId });
    } else {
      next = tick(next, `${prefix}.tick.${attempt}`);
    }
  }
  throw new Error("Encounter did not become question-ready.");
}

function answer(state: GameState, encounterId: string, correct: boolean, prefix: string, reviewedAtMs: number): GameState {
  const question = getCurrentQuestion(state, encounterId)!;
  const choice = question.node.answerChoices.find((item) => item.isCorrect === correct)!;
  return gameReducer(state, {
    type: "SUBMIT_ANSWER",
    operationId: `${prefix}.answer`,
    encounterId,
    decisionNodeId: question.node.id,
    answerChoiceId: choice.id,
    reviewedAtMs,
  });
}

function acknowledge(state: GameState, encounterId: string, prefix: string): GameState {
  const encounter = state.encounters[encounterId]!;
  return gameReducer(state, {
    type: "ACKNOWLEDGE_DECISION_FEEDBACK",
    operationId: `${prefix}.ack`,
    encounterId,
    decisionNodeId: encounter.steps[encounter.currentNodeIndex]!.decisionNodeId,
  });
}

function advanceToNextNode(state: GameState, encounterId: string, prefix: string): GameState {
  const startingIndex = state.encounters[encounterId]!.currentNodeIndex;
  let next = state;
  for (let minute = 1; minute <= 700; minute += 1) {
    next = tick(next, `${prefix}.${minute}`);
    if (next.encounters[encounterId]!.currentNodeIndex > startingIndex) return next;
  }
  throw new Error("The external result did not unlock the next node.");
}

describe("twenty-concept development admission", () => {
  it("admits all 20 concepts, 80 variants, and 52 cases with unique stable IDs", () => {
    expect(TWENTY_CONCEPT_BATCH_CONCEPTS).toHaveLength(20);
    expect(TWENTY_CONCEPT_BATCH_QUESTIONS).toHaveLength(80);
    expect(TWENTY_CONCEPT_BATCH_CASES).toHaveLength(52);
    expect(new Set(TWENTY_CONCEPT_BATCH_CONCEPTS.map((item) => item.id)).size).toBe(20);
    expect(new Set(TWENTY_CONCEPT_BATCH_QUESTIONS.map((item) => item.id)).size).toBe(80);
    expect(new Set(TWENTY_CONCEPT_BATCH_CASES.map((item) => item.id)).size).toBe(52);
    for (const clinicalCase of TWENTY_CONCEPT_BATCH_CASES) {
      expect(PROTOTYPE_DOMAIN_CONTEXT.clinicalRelease.cases.find((item) => item.id === clinicalCase.id)).toBeDefined();
    }
  });

  it("offers the three new services externally at every reached facility stage", () => {
    for (const level of [0, 1, 2] as const) {
      const state = emptyState(`routes-${level}`, level);
      for (const [serviceId, routeId] of [
        ["service.colonoscopy", "route.colonoscopy.outsourced"],
        ["service.upper_endoscopy_duodenal_biopsy", "route.upper_endoscopy_duodenal_biopsy.outsourced"],
        ["service.extremity_mri", "route.extremity_mri.outsourced"],
      ] as const) {
        expect(getEligibleServiceRoute(state, serviceId)).toMatchObject({ route: { id: routeId, requiredCapabilityIds: [] } });
      }
    }
  });

  it("enforces production facility-stage floors for two- and three-node cases", () => {
    const admit = (state: GameState, caseId: string, operationId: string) => gameReducer(state, {
      type: "ADMIT_PATIENT", operationId, encounterId: `encounter.${operationId}`, caseId,
      patientDisplayName: "Stage Test Patient", arrivalClass: "routine",
    });
    let state = admit(emptyState("stage-gallstone-zero", 0), "case.gallstones.symptomatic-postmeal-episodes", "stage.gallstone.zero");
    expect(state.operationReceipts["stage.gallstone.zero"]?.message).toBe("This patient becomes eligible at Level 1.");
    state = admit(emptyState("stage-gallstone-one", 1), "case.gallstones.symptomatic-postmeal-episodes", "stage.gallstone.one");
    expect(state.operationReceipts["stage.gallstone.one"]?.status).toBe("applied");
    state = admit(emptyState("stage-celiac-one", 1), "case.celiac.chronic-diarrhea", "stage.celiac.one");
    expect(state.operationReceipts["stage.celiac.one"]?.message).toBe("This patient becomes eligible at Level 2.");
    state = admit(emptyState("stage-celiac-two", 2), "case.celiac.chronic-diarrhea", "stage.celiac.two");
    expect(state.operationReceipts["stage.celiac.two"]?.status).toBe("applied");
  });

  it("shuffles the same question across admissions while preserving its key", () => {
    const orders = new Set<string>();
    for (let seed = 0; seed < 12; seed += 1) {
      const encounterId = `encounter.shuffle.${seed}`;
      let state = gameReducer(emptyState(`shuffle-${seed}`, 1), {
        type: "ADMIT_PATIENT", operationId: `shuffle.admit.${seed}`, encounterId,
        caseId: "case.gallstones.incidental-checkup", patientDisplayName: "Shuffle Patient", arrivalClass: "routine",
      });
      state = ready(state, encounterId, `shuffle.ready.${seed}`);
      const choices = getCurrentQuestion(state, encounterId)!.node.answerChoices;
      orders.add(choices.map((choice) => choice.id).join("|"));
      expect(choices.filter((choice) => choice.isCorrect)).toHaveLength(1);
      expect(choices.find((choice) => choice.isCorrect)?.id).toBe("observe_1");
    }
    expect(orders.size).toBeGreaterThan(1);
  });

  it("freezes automatic identity, selected demographics, and matching appearance together", () => {
    let state: GameState | undefined;
    for (let seed = 0; seed < 100 && !state; seed += 1) {
      const candidate = emptyState(`auto-identity-${seed}`, 1);
      candidate.nextRoutineArrivalTick = candidate.facilityTick + 1;
      const admitted = tick(candidate, `batch.auto-identity.arrival.${seed}`);
      const encounter = Object.values(admitted.encounters)[0];
      if (encounter && TWENTY_CONCEPT_BATCH_CASES.some((item) => item.id === encounter.frozenCase.id)) state = admitted;
    }
    expect(state).toBeDefined();
    const encounterId = Object.keys(state!.encounters)[0]!;
    const encounter = state!.encounters[encounterId]!;
    const demographics = encounter.frozenCase.prototypeDemographics!;
    expect(encounter.frozenCase.patientDisplayName).toBe(encounter.patientDisplayName);
    expect(encounter.frozenCase.presentation).toContain(encounter.patientDisplayName);
    expect(encounter.frozenCase.presentation).not.toContain("{patientName}");
    expect(encounter.patientAppearance).toEqual(createPatientPixelAppearance(state!.campaignSeed, encounterId, demographics));
    expect(encounter.frozenCase.selectedInstantiationProfileId).toBeTruthy();
  });

  it("honors literal manual names and preserves the frozen name through serialization", () => {
    const encounterId = "encounter.batch.manual-name";
    const name = "Taylor $& {patientName}";
    const state = gameReducer(emptyState("manual-name", 1), {
      type: "ADMIT_PATIENT",
      operationId: "batch.manual-name.admit",
      encounterId,
      caseId: "case.gallstones.incidental-checkup",
      patientDisplayName: name,
      arrivalClass: "routine",
    });
    expect(state.encounters[encounterId]!.frozenCase.presentation).toContain(name);
    const restored = deserializeGameState(serializeGameState(state));
    expect(restored.encounters[encounterId]!.patientDisplayName).toBe(name);
    expect(restored.encounters[encounterId]!.frozenCase).toEqual(state.encounters[encounterId]!.frozenCase);
  });

  it("requires both celiac services before later questions and records three FSRS concept reviews", () => {
    const encounterId = "encounter.batch.celiac";
    let state = gameReducer(emptyState("celiac-flow", 2), {
      type: "ADMIT_PATIENT",
      operationId: "batch.celiac.admit",
      encounterId,
      caseId: "case.celiac.chronic-diarrhea",
      patientDisplayName: "Celiac Flow Patient",
      arrivalClass: "routine",
    });
    state = ready(state, encounterId, "celiac.first");
    expect(getCurrentQuestion(state, encounterId)!.node.primaryConceptId).toBe("concept.celiac.initial-serology");
